					int leftAdj = (e.ColumnIndex == 0) ? 0 : 1;
					e.Graphics.DrawLine(thinPen, e.CellBounds.Left, e.CellBounds.Top - topAdj, e.CellBounds.Right, e.CellBounds.Top - topAdj);
