							if (side == BorderSide.Bottom)
							{
								penWidth = 2;
								int x1 = e.CellBounds.Left;
								int y = e.CellBounds.Bottom - penWidth / 2 - 1;
								int x2 = e.CellBounds.Right - 1;
								e.Graphics.DrawLine(thickPen, x1, y, x2, y);
							}
