							{
								sBox.BackColor = Color.White;
								break;
							}
						}
						else
						{
							break;
						}
					}
					clickedTB.BackColor = Color.White;
					clickedTB.Text = "_";
				}
				if (clickedTB.Text == "_")
				{
					for (int j = 0; j < 20; j++)
